@import url('https://fonts.googleapis.com/css2?family=Vazirmatn:wght@100..900&display=swap');

:root{
 --ir-font-family:"Vazirmatn",sans-serif!important;
}

/* New Class Request hard override — intentionally high specificity */
html body #root .ir-screen-surface:has(.ir-new-class-request){
 width:100%!important;
 max-width:none!important;
 height:100%!important;
 min-height:100%!important;
 margin:0!important;
 padding:0!important;
 overflow:hidden!important;
 background:#fff9df!important;
}

html body #root .ir-screen-surface:has(.ir-new-class-request)>*{
 width:100%!important;
 max-width:none!important;
 margin:0!important;
}

html body #root .ir-new-class-request,
html body #root .ir-new-class-request *{
 box-sizing:border-box!important;
 font-family:var(--ir-font-family)!important;
}

html body #root .ir-new-class-request{
 display:block!important;
 width:100%!important;
 max-width:none!important;
 min-height:100%!important;
 height:100%!important;
 margin:0!important;
 padding:max(34px,env(safe-area-inset-top)) clamp(22px,6vw,38px) max(32px,env(safe-area-inset-bottom))!important;
 overflow-x:hidden!important;
 overflow-y:auto!important;
 direction:rtl!important;
 color:#18181b!important;
 background:#fff9df!important;
 scrollbar-width:none!important;
 overscroll-behavior-y:contain!important;
}

html body #root .ir-new-class-request::-webkit-scrollbar{
 display:none!important;
}

html body #root .ir-new-class-request__header{
 display:grid!important;
 grid-template-columns:minmax(0,1fr) 44px!important;
 grid-template-areas:"copy back"!important;
 align-items:start!important;
 gap:14px!important;
 width:100%!important;
 max-width:none!important;
 min-height:72px!important;
 margin:0 0 30px!important;
 padding:0!important;
 direction:rtl!important;
 background:transparent!important;
 border:0!important;
}

html body #root .ir-new-class-request__header>div{
 grid-area:copy!important;
 display:block!important;
 min-width:0!important;
 margin:0!important;
 padding:0!important;
}

html body #root .ir-new-class-request__header h1{
 margin:0 0 4px!important;
 padding:0!important;
 color:#18181b!important;
 font-size:26px!important;
 font-weight:900!important;
 line-height:1.45!important;
 letter-spacing:-.025em!important;
}

html body #root .ir-new-class-request__header p{
 margin:0!important;
 padding:0!important;
 color:#77787f!important;
 font-size:11px!important;
 font-weight:500!important;
 line-height:1.8!important;
}

html body #root .ir-new-class-request__back{
 grid-area:back!important;
 display:grid!important;
 width:42px!important;
 min-width:42px!important;
 max-width:42px!important;
 height:42px!important;
 min-height:42px!important;
 max-height:42px!important;
 place-items:center!important;
 justify-self:end!important;
 margin:0!important;
 padding:0!important;
 color:#171719!important;
 background:transparent!important;
 border:0!important;
 border-radius:50%!important;
 box-shadow:none!important;
}

html body #root .ir-new-class-request__back svg{
 display:block!important;
 width:28px!important;
 height:28px!important;
 fill:none!important;
 stroke:currentColor!important;
 stroke-width:2.1!important;
 stroke-linecap:round!important;
 stroke-linejoin:round!important;
}

html body #root .ir-new-class-request__form{
 display:flex!important;
 flex-direction:column!important;
 gap:15px!important;
 width:100%!important;
 max-width:none!important;
 margin:0!important;
 padding:0!important;
}

html body #root .ir-new-class-request__card,
html body #root .ir-new-class-request__budget-card{
 display:block!important;
 width:100%!important;
 max-width:none!important;
 margin:0!important;
 padding:21px 19px!important;
 background:#fff!important;
 border:1px solid rgba(34,34,38,.035)!important;
 border-radius:20px!important;
 box-shadow:0 4px 15px rgba(44,38,14,.025)!important;
}

html body #root .ir-new-class-request__card{
 display:flex!important;
 flex-direction:column!important;
 gap:19px!important;
}

html body #root .ir-new-class-request__budget-card{
 padding-top:20px!important;
 padding-bottom:20px!important;
}

html body #root .ir-new-class-request__field{
 display:block!important;
 width:100%!important;
 min-width:0!important;
 margin:0!important;
 padding:0!important;
 color:#202024!important;
 background:transparent!important;
 border:0!important;
}

html body #root .ir-new-class-request__field>strong,
html body #root .ir-new-class-request__attachment>strong{
 display:block!important;
 margin:0 0 8px!important;
 padding:0!important;
 color:#202024!important;
 font-size:12px!important;
 font-weight:900!important;
 line-height:1.7!important;
}

html body #root .ir-new-class-request__two-columns{
 display:grid!important;
 grid-template-columns:repeat(2,minmax(0,1fr))!important;
 gap:11px!important;
 width:100%!important;
 margin:0!important;
 padding:0!important;
}

html body #root .ir-new-class-request__select,
html body #root .ir-new-class-request__input,
html body #root .ir-new-class-request__textarea,
html body #root .ir-new-class-request__budget{
 position:relative!important;
 display:block!important;
 width:100%!important;
 min-width:0!important;
 margin:0!important;
 padding:0!important;
 overflow:hidden!important;
 color:#242428!important;
 background:#fff!important;
 border:1px solid #d8d9de!important;
 border-radius:12px!important;
 box-shadow:none!important;
}

html body #root .ir-new-class-request__select,
html body #root .ir-new-class-request__input,
html body #root .ir-new-class-request__budget{
 height:48px!important;
 min-height:48px!important;
}

html body #root .ir-new-class-request__select:focus-within,
html body #root .ir-new-class-request__input:focus-within,
html body #root .ir-new-class-request__textarea:focus-within,
html body #root .ir-new-class-request__budget:focus-within{
