 box-shadow:0 0 0 3px rgba(255,209,0,.09)!important;
}

html body #root .ir-new-class-request__select.has-error,
html body #root .ir-new-class-request__input.has-error,
html body #root .ir-new-class-request__textarea.has-error,
html body #root .ir-new-class-request__budget.has-error{
 border-color:#dc5753!important;
}

html body #root .ir-new-class-request__select select{
 display:block!important;
 width:100%!important;
 min-width:0!important;
 height:46px!important;
 margin:0!important;
 padding:0 13px 0 39px!important;
 appearance:none!important;
 -webkit-appearance:none!important;
 direction:rtl!important;
 color:#28282c!important;
 background:#fff!important;
 border:0!important;
 border-radius:0!important;
 outline:0!important;
 box-shadow:none!important;
 font-size:11px!important;
 font-weight:600!important;
 line-height:46px!important;
}

html body #root .ir-new-class-request__select select:disabled{
 color:#a1a2a8!important;
 background:#f8f8f8!important;
 opacity:1!important;
}

html body #root .ir-new-class-request__select>svg{
 position:absolute!important;
 top:50%!important;
 left:12px!important;
 display:block!important;
 width:19px!important;
 height:19px!important;
 pointer-events:none!important;
 fill:none!important;
 stroke:#98999f!important;
 stroke-width:2.2!important;
 stroke-linecap:round!important;
 stroke-linejoin:round!important;
 transform:translateY(-50%)!important;
}

html body #root .ir-new-class-request__input input{
 display:block!important;
 width:100%!important;
 min-width:0!important;
 height:46px!important;
 margin:0!important;
 padding:0 13px!important;
 direction:rtl!important;
 color:#28282c!important;
 background:#fff!important;
 border:0!important;
 border-radius:0!important;
 outline:0!important;
 box-shadow:none!important;
 font-size:11px!important;
 font-weight:600!important;
 line-height:46px!important;
}

html body #root .ir-new-class-request__textarea{
 min-height:122px!important;
 overflow:hidden!important;
}

html body #root .ir-new-class-request__textarea textarea{
 display:block!important;
 width:100%!important;
 min-width:0!important;
 min-height:122px!important;
 max-height:220px!important;
 margin:0!important;
 padding:12px 13px!important;
 resize:vertical!important;
 direction:rtl!important;
 color:#28282c!important;
 background:#fff!important;
 border:0!important;
 border-radius:0!important;
 outline:0!important;
 box-shadow:none!important;
 font-size:11px!important;
 font-weight:500!important;
 line-height:1.9!important;
}

html body #root .ir-new-class-request__input input::placeholder,
html body #root .ir-new-class-request__textarea textarea::placeholder,
html body #root .ir-new-class-request__budget input::placeholder{
 color:#a0a1a7!important;
 opacity:1!important;
}

html body #root .ir-new-class-request__error{
 display:block!important;
 margin:5px 2px 0!important;
 padding:0!important;
 color:#cf4541!important;
 font-size:8px!important;
 font-weight:700!important;
 line-height:1.6!important;
}

html body #root .ir-new-class-request__attachment{
 display:block!important;
 width:100%!important;
 margin:0!important;
 padding:0!important;
}

html body #root .ir-new-class-request__upload{
 display:flex!important;
 flex-direction:column!important;
 align-items:center!important;
 justify-content:center!important;
 gap:8px!important;
 width:100%!important;
 min-height:108px!important;
 margin:0!important;
 padding:13px!important;
 color:#171719!important;
 background:#fff!important;
 border:1.5px dashed #d4d5da!important;
 border-radius:12px!important;
 box-shadow:none!important;
}

html body #root .ir-new-class-request__upload>span{
 display:grid!important;
 width:44px!important;
 height:44px!important;
 place-items:center!important;
 color:#171719!important;
 background:#ffd100!important;
 border-radius:50%!important;
}

html body #root .ir-new-class-request__upload svg{
 display:block!important;
 width:25px!important;
 height:25px!important;
 fill:none!important;
 stroke:currentColor!important;
 stroke-width:2!important;
 stroke-linecap:round!important;
 stroke-linejoin:round!important;
}

html body #root .ir-new-class-request__upload small{
 display:block!important;
 margin:0!important;
 color:#999aa1!important;
 font-size:9px!important;
 font-weight:500!important;
 line-height:1.7!important;
 text-align:center!important;
}

html body #root .ir-new-class-request__attachment-file{
 display:grid!important;
 grid-template-columns:48px minmax(0,1fr) 28px!important;
 align-items:center!important;
 gap:10px!important;
 width:100%!important;
 min-height:66px!important;
 margin:0!important;
 padding:8px 9px!important;
 direction:ltr!important;
 background:#f7f7f8!important;
 border:1px solid #dedfe3!important;
 border-radius:12px!important;
}

html body #root .ir-new-class-request__attachment-file.is-error{
 background:#fff1f1!important;
 border-color:#e98f8b!important;
}

html body #root .ir-new-class-request__attachment-preview{
 display:grid!important;
 grid-column:1!important;
 width:46px!important;
 height:46px!important;
 place-items:center!important;
 overflow:hidden!important;
 color:#6e6f75!important;
 background:#e5e5e7!important;
 border-radius:8px!important;
}

html body #root .ir-new-class-request__attachment-preview img{
 display:block!important;
 width:100%!important;
 height:100%!important;
 object-fit:cover!important;
}

html body #root .ir-new-class-request__attachment-preview svg{
 width:24px!important;
 height:24px!important;
 fill:none!important;
 stroke:currentColor!important;
 stroke-width:1.8!important;
 stroke-linecap:round!important;
 stroke-linejoin:round!important;
}

html body #root .ir-new-class-request__attachment-file>div{
 grid-column:2!important;
 min-width:0!important;
 direction:rtl!important;
 text-align:right!important;
}

html body #root .ir-new-class-request__attachment-file>div strong{
 display:block!important;
 overflow:hidden!important;
 color:#29292d!important;
 font-size:10px!important;
 font-weight:800!important;
 text-overflow:ellipsis!important;
 white-space:nowrap!important;
}

html body #root .ir-new-class-request__attachment-file>div small{
 display:block!important;
 margin-top:3px!important;
 overflow:hidden!important;
 color:#888990!important;
 font-size:8px!important;
 text-overflow:ellipsis!important;
 white-space:nowrap!important;
}

html body #root .ir-new-class-request__attachment-file>button{
 grid-column:3!important;
 display:grid!important;
 width:25px!important;
 height:25px!important;
 place-items:center!important;
 margin:0!important;
 padding:0!important;
 color:#73747b!important;
 background:#e4e4e6!important;
 border:0!important;
 border-radius:50%!important;
 box-shadow:none!important;
 font-size:17px!important;
 line-height:1!important;
}

html body #root .ir-new-class-request__native-file{
 position:absolute!important;
 width:1px!important;
 height:1px!important;
 margin:0!important;
 padding:0!important;
 overflow:hidden!important;
 opacity:0!important;
 pointer-events:none!important;
}

html body #root .ir-new-class-request__budget{
 display:grid!important;
 grid-template-columns:minmax(0,1fr) auto!important;
 align-items:center!important;
 direction:ltr!important;
}

html body #root .ir-new-class-request__budget input{
 grid-column:1!important;
 display:block!important;
 width:100%!important;
 min-width:0!important;
 height:46px!important;
 margin:0!important;
 padding:0 13px!important;
 direction:rtl!important;
 color:#28282c!important;
 background:#fff!important;
 border:0!important;
 outline:0!important;
 box-shadow:none!important;
 font-size:11px!important;
 font-weight:600!important;
}

html body #root .ir-new-class-request__budget b{
 grid-column:2!important;
 display:block!important;
 padding:0 13px!important;
 color:#77787f!important;
 font-size:9px!important;
 font-weight:700!important;
 white-space:nowrap!important;
}

html body #root .ir-new-class-request__submit{
 display:block!important;
 width:100%!important;
 min-height:58px!important;
 margin:0!important;
 padding:10px 18px!important;
 color:#171719!important;
 background:#ffd100!important;
 border:0!important;
 border-radius:15px!important;
 box-shadow:none!important;
 font-size:15px!important;
 font-weight:900!important;
 line-height:1.5!important;
}

html body #root .ir-new-class-request__submit:active{
 transform:scale(.992)!important;
}

@media(max-width:420px){
 html body #root .ir-new-class-request{
  padding-right:22px!important;
  padding-left:22px!important;
 }

 html body #root .ir-new-class-request__header{
  margin-bottom:26px!important;
 }

 html body #root .ir-new-class-request__header h1{
  font-size:24px!important;
 }

 html body #root .ir-new-class-request__card,
 html body #root .ir-new-class-request__budget-card{
  padding-right:17px!important;
  padding-left:17px!important;
 }

 html body #root .ir-new-class-request__two-columns{
  gap:9px!important;
 }

 html body #root .ir-new-class-request__field>strong,
 html body #root .ir-new-class-request__attachment>strong{
  font-size:11px!important;
 }
}

@media(max-width:350px){
 html body #root .ir-new-class-request{
  padding-right:17px!important;
  padding-left:17px!important;
 }

 html body #root .ir-new-class-request__two-columns{
  grid-template-columns:1fr!important;
 }

 html body #root .ir-new-class-request__header h1{
  font-size:22px!important;
 }
}

@media(min-width:700px){
 html body #root .ir-new-class-request{
  padding-right:clamp(32px,7vw,64px)!important;
  padding-left:clamp(32px,7vw,64px)!important;
 }

 html body #root .ir-new-class-request__header,
 html body #root .ir-new-class-request__form{
  width:min(760px,100%)!important;
  margin-right:auto!important;
  margin-left:auto!important;
 }
}

html,
body,
#root,
body :where(*):not(.material-symbols-outlined):not(.material-symbols-rounded):not(.material-symbols-sharp),
