.ir-credential-back-button,
.ir-ref-otp__underlay > button,
.ir-parent-login-button {
  display:none!important;
}

/* SVG iteration 04: role selection */
.ir-ref-role-selection {
  display:grid;
  place-items:center;
  min-height:100vh;
  padding:48px 24px;
  background:#f7f7f7;
}

.ir-ref-role-selection__card {
  display:flex;
  flex-direction:column;
  width:min(600px,100%);
  min-height:804px;
  padding:48px;
  overflow:hidden;
  background:#fff;
  border:1px solid #dfe1e6;
  border-radius:24px;
}

.ir-ref-role-selection__steps {
  display:flex;
  align-items:center;
  justify-content:center;
  gap:10px;
  margin-bottom:42px;
  direction:rtl;
}

.ir-ref-role-selection__steps span {
  display:inline-flex;
  align-items:center;
  gap:8px;
  min-height:38px;
  padding:8px 15px;
  color:#a0a1a7;
  white-space:nowrap;
  background:#fff;
  border:1px solid #dfe1e6;
  border-radius:999px;
}

.ir-ref-role-selection__steps span.is-active,
.ir-ref-role-selection__steps span.is-complete {
  color:#202024;
  background:#ffcc00;
  border-color:#ffcc00;
}

.ir-ref-role-selection__steps i {
  font-size:16px;
  font-style:normal;
}

.ir-ref-role-selection__steps b {
  font-size:12px;
}

.ir-ref-role-selection__header {
  text-align:center;
}

.ir-ref-role-selection__header h1 {
  margin-bottom:12px;
  color:#202024;
  font-size:36px;
  line-height:1.35;
}

.ir-ref-role-selection__header p {
  margin-bottom:34px;
  color:#9a9ba1;
  font-size:14px;
}

.ir-ref-role-selection__notice {
  display:flex;
  align-items:center;
  gap:11px;
  min-height:46px;
  margin-bottom:38px;
  padding:11px 15px;
  color:#303034;
  background:#fffefa;
  border:1px solid #f1d875;
  border-radius:14px;
}

.ir-ref-role-selection__notice > span {
  color:#f2bd00;
  font-size:18px;
}

.ir-ref-role-selection__notice strong {
  font-size:11px;
  line-height:1.8;
}

.ir-ref-role-selection__grid {
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:14px;
  direction:rtl;
}

.ir-ref-role-option {
  position:relative;
  display:flex;
  flex-direction:column;
  align-items:flex-start;
  gap:7px;
  min-height:114px;
  padding:38px 18px 16px;
  color:#242428;
  text-align:right;
  background:#fff;
  border:1px solid #dfe1e6;
  border-radius:15px;
  transition:border-color .18s,background .18s,box-shadow .18s,transform .18s;
}

.ir-ref-role-option:hover:not(:disabled) {
  border-color:#ffcc00;
  box-shadow:0 10px 24px rgba(25,25,28,.06);
  transform:translateY(-2px);
}

.ir-ref-role-option.is-selected {
  padding:37px 17px 15px;
  background:#fffdf4;
  border:2px solid #ffcc00;
}

.ir-ref-role-option:disabled {
  cursor:not-allowed;
  opacity:1;
}

.ir-ref-role-option.is-disabled {
  color:#85868d;
  background:#fff;
}

.ir-ref-role-option strong {
  font-size:13px;
}

.ir-ref-role-option small {
  color:#999ba2;
  font-size:10px;
  line-height:1.8;
}

.ir-ref-role-option__icon {
  position:absolute;
  top:11px;
  left:11px;
  display:grid;
  place-items:center;
  width:28px;
  height:28px;
  color:#a1a2a8;
  background:#f4f4f6;
  border-radius:9px;
}

.ir-ref-role-option.is-selected .ir-ref-role-option__icon {
  color:#202024;
  background:#fff0ad;
}

.ir-ref-role-option__selected {
  position:absolute;
  top:15px;
  right:15px;
  display:grid;
  place-items:center;
  width:20px;
  height:20px;
  color:#fff;
  font-size:12px;
  font-weight:1000;
  background:#ffcc00;
  border-radius:50%;
}

.ir-ref-role-selection__relationship-note {
  margin:14px 0 30px;
  color:#9a9ba1;
  font-size:10px;
  text-align:center;
}

.ir-ref-role-selection__selected {
  display:flex;
  align-items:center;
  justify-content:center;
  gap:10px;
  flex-wrap:wrap;
  margin-bottom:50px;
  color:#9a9ba1;
  font-size:12px;
}

.ir-ref-role-selection__selected strong {
  padding:7px 16px;
  color:#202024;
  font-size:12px;
  background:#ffcc00;
  border-radius:999px;
}

.ir-ref-role-selection__card > .ir-button {
  margin-top:auto;
}

/* SVG iteration 05: onboarding */
.ir-ref-onboarding {
  display:grid;
  place-items:center;
  min-height:100vh;
  padding:40px;
  background:#fff9df;
}

.ir-ref-onboarding__shell {
  display:grid;
  grid-template-columns:1.08fr .92fr;
  width:min(1080px,100%);
  min-height:690px;
  overflow:hidden;
  direction:ltr;
  background:#fff9df;
  border:1px solid rgba(25,25,28,.08);
  border-radius:32px;
  box-shadow:0 26px 70px rgba(53,44,10,.08);
}

.ir-ref-onboarding__visual {
  display:grid;
  place-items:center;
  margin:30px;
  overflow:hidden;
  direction:rtl;
  background:#fff;
  border-radius:28px;
}

.ir-ref-onboarding__visual.is-welcome {
  background:#fff4b7;
}

.ir-ref-onboarding__visual .ir-onboarding-svg {
  display:block;
  width:100%;
  height:auto;
  max-height:520px;
}

.ir-ref-onboarding__content {
  display:flex;
  flex-direction:column;
  min-width:0;
  padding:58px 56px 48px;
  direction:rtl;
}

.ir-ref-onboarding__brand {
  display:inline-flex;
  align-items:center;
  align-self:flex-start;
  gap:8px;
  padding:9px 14px;
  color:#1e1e21;
  font-size:12px;
  font-weight:1000;
  background:rgba(255,255,255,.72);
  border:1px solid rgba(25,25,28,.09);
  border-radius:999px;
}

.ir-ref-onboarding__brand b {
  color:#b88d00;
}

.ir-ref-onboarding__copy {
  margin:auto 0;
  text-align:right;
}

.ir-ref-onboarding__copy h1 {
  margin:0 0 20px;
  color:#1b1b1e;
  font-size:42px;
  font-weight:1000;
  line-height:1.35;
}

.ir-ref-onboarding__copy p {
  max-width:460px;
  margin:0;
  color:#8e8e94;
  font-size:17px;
  line-height:2;
}

.ir-ref-onboarding__dots {
  display:flex;
  align-items:center;
  justify-content:center;
  gap:8px;
  margin-bottom:30px;
  direction:ltr;
}

.ir-ref-onboarding__dots button {
  width:9px;
  height:9px;
  padding:0;
  background:#dddfe4;
  border:0;
  border-radius:999px;
  transition:width .18s,background .18s;
}

.ir-ref-onboarding__dots button.is-active {
  width:28px;
  background:#ffcb00;
}

.ir-ref-onboarding__actions {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:18px;
}

.ir-ref-onboarding__actions .ir-button {
  min-width:170px;
}

.ir-ref-onboarding__actions.is-single .ir-button {
  width:100%;
}

.ir-ref-onboarding__skip {
  padding:14px 0;
  color:#8e8e94;
  font-size:14px;
  font-weight:900;
  background:transparent;
  border:0;
}

.ir-ref-onboarding__skip:hover {
  color:#242428;
}

.ir-ref-onboarding__shell.is-welcome .ir-ref-onboarding__brand {
  align-self:center;
}

.ir-ref-onboarding__shell.is-welcome .ir-ref-onboarding__copy {
  text-align:center;
}

.ir-ref-onboarding__shell.is-welcome .ir-ref-onboarding__copy p {
  margin-right:auto;
  margin-left:auto;
}

.ir-ref-onboarding__shell.is-welcome .ir-ref-onboarding__content {
  justify-content:center;
}

@media(max-width:900px) {
  .ir-ref-onboarding {
    padding:20px;
  }

  .ir-ref-onboarding__shell {
    grid-template-columns:1fr;
    max-width:680px;
  }

  .ir-ref-onboarding__visual {
