  --ir-svg-shield:url("data:image/svg+xml;base64,");
  --ir-svg-lock:url("data:image/svg+xml;base64,");
  --ir-svg-users:url("data:image/svg+xml;base64,");
  --ir-svg-building:url("data:image/svg+xml;base64,");
  --ir-svg-graduation:url("data:image/svg+xml;base64,");
  --ir-svg-user:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAyNCAyNCIgZmlsbD0ibm9uZSIgc3Ryb2tlPSJibGFjayIgc3Ryb2tlLXdpZHRoPSIyIiBzdHJva2UtbGluZWNhcD0icm91bmQiIHN0cm9rZS1saW5lam9pbj0icm91bmQiPjxjaXJjbGUgY3g9IjEyIiBjeT0iOCIgcj0iNSIvPjxwYXRoIGQ9Ik0yMCAyMWE4IDggMCAwIDAtMTYgMCIvPjwvc3ZnPg==");
  --ir-svg-eye:url("data:image/svg+xml;base64,");
  --ir-svg-check:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAyNCAyNCIgZmlsbD0ibm9uZSIgc3Ryb2tlPSJibGFjayIgc3Ryb2tlLXdpZHRoPSIyLjUiIHN0cm9rZS1saW5lY2FwPSJyb3VuZCIgc3Ryb2tlLWxpbmVqb2luPSJyb3VuZCI+PHBhdGggZD0ibTIwIDYtMTEgMTEtNS01Ii8+PC9zdmc+");
  --ir-svg-pencil:url("data:image/svg+xml;base64,");
}

.ir-identity-avatar{
  overflow:hidden;
  background-color:transparent!important;
  background-image:url("data:image/svg+xml;base64,")!important;
  background-position:center!important;
  background-repeat:no-repeat!important;
  background-size:cover!important;
  border:0!important;
  box-shadow:none!important;
}

.ir-identity-avatar>span{
  display:none!important;
}

.ir-ref-onboarding__visual.is-welcome .ir-onboarding-svg{
  visibility:hidden;
}

.ir-ref-onboarding__visual.is-welcome{
  position:relative;
  background:#fff4b7;
}

.ir-ref-onboarding__visual.is-welcome::before{
  content:"";
  position:absolute;
  inset:12%;
  background-image:url("data:image/svg+xml;base64,");
  background-position:center;
  background-repeat:no-repeat;
  background-size:contain;
}

.ir-ref-student-auth__brand .ir-icon,
.ir-identity-profile small .ir-icon,
.ir-identity-info .ir-icon,
.ir-identity-linked-account .ir-icon,
.ir-identity-security-badge .ir-icon,
.ir-ref-role-option__icon .ir-icon{
  display:inline-block!important;
  flex:0 0 auto;
  color:inherit;
  font-size:0!important;
  line-height:0!important;
  background-color:currentColor;
  -webkit-mask-position:center;
  mask-position:center;
  -webkit-mask-repeat:no-repeat;
  mask-repeat:no-repeat;
  -webkit-mask-size:contain;
  mask-size:contain;
}

.ir-ref-student-auth__brand .ir-icon{
  -webkit-mask-image:var(--ir-svg-book);
  mask-image:var(--ir-svg-book);
}

.ir-identity-profile small .ir-icon,
.ir-identity-linked-account .ir-icon{
  -webkit-mask-image:var(--ir-svg-lock);
  mask-image:var(--ir-svg-lock);
}

.ir-identity-info .ir-icon,
.ir-identity-security-badge .ir-icon{
  -webkit-mask-image:var(--ir-svg-shield);
  mask-image:var(--ir-svg-shield);
}

.ir-ref-role-option:nth-child(1) .ir-icon{
  -webkit-mask-image:var(--ir-svg-users);
  mask-image:var(--ir-svg-users);
}

.ir-ref-role-option:nth-child(2) .ir-icon{
  -webkit-mask-image:var(--ir-svg-building);
  mask-image:var(--ir-svg-building);
}

.ir-ref-role-option:nth-child(3) .ir-icon{
  -webkit-mask-image:var(--ir-svg-graduation);
  mask-image:var(--ir-svg-graduation);
}

.ir-ref-role-option:nth-child(4) .ir-icon{
  -webkit-mask-image:var(--ir-svg-user);
  mask-image:var(--ir-svg-user);
}

.ir-ref-role-option:nth-child(5) .ir-icon{
  -webkit-mask-image:var(--ir-svg-shield);
  mask-image:var(--ir-svg-shield);
}

.ir-identity-password-eye{
  width:20px;
  height:20px;
  background:#d9dce4;
  border:0;
  border-radius:0;
  -webkit-mask-image:var(--ir-svg-eye);
  mask-image:var(--ir-svg-eye);
  -webkit-mask-position:center;
  mask-position:center;
  -webkit-mask-repeat:no-repeat;
  mask-repeat:no-repeat;
  -webkit-mask-size:contain;
  mask-size:contain;
}

.ir-identity-password-eye::after{
  display:none;
}

.ir-identity-password-eye.is-visible{
  background:#c29900;
  border:0;
}

.ir-ref-role-selection__steps i,
.ir-otp-lock-glyph{
  display:inline-block;
  width:17px;
  height:17px;
  color:inherit;
  font-size:0;
  background-color:currentColor;
  -webkit-mask-position:center;
  mask-position:center;
  -webkit-mask-repeat:no-repeat;
  mask-repeat:no-repeat;
  -webkit-mask-size:contain;
  mask-size:contain;
}

.ir-ref-role-selection__steps .is-complete i{
  -webkit-mask-image:var(--ir-svg-check);
  mask-image:var(--ir-svg-check);
}

.ir-ref-role-selection__steps .is-active i{
  -webkit-mask-image:var(--ir-svg-pencil);
  mask-image:var(--ir-svg-pencil);
}

.ir-ref-role-selection__steps .is-locked i,
.ir-otp-lock-glyph{
  -webkit-mask-image:var(--ir-svg-lock);
  mask-image:var(--ir-svg-lock);
}

.ir-ref-student-auth__layout{
  direction:rtl;
  grid-template-columns:1.1fr .9fr;
}

.ir-ref-student-auth__main{
  grid-column:1;
  direction:rtl;
  text-align:right;
}

.ir-ref-student-auth__promo{
  grid-column:2;
  direction:rtl;
  text-align:right;
}

.ir-ref-auth-card,
.ir-ref-credential__form,
.ir-ref-otp__card,
.ir-ref-role-selection__card,
.ir-ref-role-selection__grid,
.ir-ref-role-option{
  direction:rtl;
  text-align:right;
}

.ir-ref-auth-card .ir-field,
.ir-ref-credential__form .ir-field,
.ir-ref-credential__form .ir-identity-password-field,
.ir-ref-auth-card input,
.ir-ref-credential__form input,
.ir-identity-auth-tabs{
  direction:rtl;
  text-align:right;
}

.ir-ref-role-option__icon{
  right:auto;
  left:11px;
}

.ir-ref-role-option__selected{
  right:15px;
  left:auto;
}

.ir-ref-onboarding__shell{
  direction:rtl;
  grid-template-columns:.92fr 1.08fr;
}

.ir-ref-onboarding__content{
  grid-column:1;
  grid-row:1;
  direction:rtl;
  text-align:right;
}

.ir-ref-onboarding__visual{
  grid-column:2;
  grid-row:1;
  direction:rtl;
}

@media(max-width:900px){
  .ir-ref-student-auth__main,
  .ir-ref-student-auth__promo{
    grid-column:1;
  }

  .ir-ref-onboarding__visual{
    grid-column:1;
    grid-row:1;
  }

  .ir-ref-onboarding__content{
    grid-column:1;
    grid-row:2;
  }
}

/* Final SVG identity implementation overrides */
.ir-identity-browser-dots,
.ir-identity-phone-status,
.ir-identity-home-indicator,
.ir-ref-back-button,
.ir-credential-back-button,
.ir-parent-login-button{display:none!important}
.ir-brand-mark{display:block;width:min(100%,370px);height:auto;object-fit:contain}
.ir-brand-mark.is-compact{width:112px}
.ir-identity-avatar{overflow:hidden;background:none!important;border:2px solid #ffd100!important;border-radius:50%}
.ir-identity-avatar>span{display:none!important}
.ir-identity-avatar>img{display:block!important;width:100%;height:100%;object-fit:cover;object-position:center 28%}
.ir-button--dark-auth{color:#fff;background:#69696d;border-color:#69696d;box-shadow:none}
.ir-button--dark-auth:hover{background:#77777b}
.ir-identity-otp-fields{grid-template-columns:repeat(5,minmax(0,1fr))}
