.ir-prototype-identity-auth__divider:before,.ir-prototype-identity-auth__divider:after{content:"";flex:1;height:1px;background:#48484d}
.ir-prototype-identity-auth__alternatives{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.ir-prototype-identity-auth__alternatives button{min-height:44px;padding:8px;color:#dddde1;background:#242428;border:1px solid #505056;border-radius:11px}
.ir-prototype-terms{position:fixed;inset:0;z-index:300;display:grid;place-items:center;padding:20px;background:rgba(0,0,0,.72)}
.ir-prototype-terms>section{width:min(620px,100%);max-height:min(760px,90svh);overflow:auto;color:#eeeef1;background:#2a2a2e;border:1px solid #55555b;border-radius:20px;box-shadow:0 30px 90px rgba(0,0,0,.45)}
.ir-prototype-terms header{position:sticky;top:0;display:grid;grid-template-columns:34px 1fr 34px;align-items:center;gap:12px;padding:17px 20px;background:#2a2a2e;border-bottom:1px solid #48484d}
.ir-prototype-terms header h2{margin:0;text-align:center;font-size:16px}
.ir-prototype-terms header button{display:grid;place-items:center;width:34px;height:34px;padding:0;color:#dddde1;background:transparent;border:0}
.ir-prototype-terms header button svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round}
.ir-prototype-terms header>svg{color:#ffd100}
