.ir-prototype-terms article:last-child{border-bottom:0}
.ir-prototype-terms article h3{margin-bottom:7px;color:#fff;font-size:13px}
.ir-prototype-terms article p{margin:0;color:#aaaab0;font-size:11px;line-height:2}

.ir-prototype-activation{display:grid;grid-template-areas:"top rail" "main rail";grid-template-columns:minmax(0,1fr) 220px;grid-template-rows:40px minmax(0,1fr);min-height:100vh;background:#f7f7f7}
.ir-prototype-activation__rail{grid-area:rail;display:flex;justify-content:flex-start;padding:24px 16px;background:#111}
.ir-prototype-activation__rail>.ir-brand-mark{width:118px;height:auto;align-self:flex-start;padding:4px;background:#ffd100;border-radius:999px}
.ir-prototype-activation__top{grid-area:top;display:flex;align-items:center;justify-content:space-between;padding:0 30px;background:#fff;border-bottom:1px solid #e5e5ea}
