.ir-prototype-activation__card{grid-area:main;align-self:center;justify-self:center;display:flex;flex-direction:column;align-items:center;width:min(560px,calc(100% - 40px));min-height:790px;padding:28px 40px;background:#fff;border:1px solid #e5e5ea;border-radius:20px}
