.ir-prototype-activation__orb i{position:absolute;border-radius:50%}
.ir-prototype-activation__orb i:nth-child(1){width:340px;height:340px;background:#f4f4f5}
.ir-prototype-activation__orb i:nth-child(2){width:260px;height:260px;background:#fff8d7}
.ir-prototype-activation__orb i:nth-child(3){width:180px;height:180px;background:radial-gradient(circle,#fff 0,#ffe566 28%,#ffd100 58%,#f7c400 100%)}
.ir-prototype-activation__card h1{margin-bottom:14px;font-size:21px}
.ir-prototype-activation__card>p{margin-bottom:26px;color:#8e8e93;font-size:11px;text-align:center}
.ir-prototype-activation__status{width:100%;padding:22px;background:#fff;border:1px solid #e5e7eb;border-radius:12px}
.ir-prototype-activation__status h2{margin-bottom:18px;font-size:13px}
.ir-prototype-activation__status>div{display:flex;align-items:center;gap:10px;padding:10px 0;color:#8e8e93;font-size:10px}
.ir-prototype-activation__status .ir-icon{font-size:0!important;background:#34c759;-webkit-mask-image:var(--ir-svg-check);mask-image:var(--ir-svg-check);-webkit-mask-position:center;mask-position:center;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;-webkit-mask-size:contain;mask-size:contain}
.ir-prototype-activation__status .is-loading .ir-icon{width:18px!important;height:18px!important;background:transparent;border:2px solid #a5a5aa;border-bottom-color:transparent;border-radius:50%;-webkit-mask-image:none;mask-image:none;animation:irspin .8s linear infinite}
.ir-prototype-activation__progress-label{display:flex;justify-content:space-between;width:100%;margin:24px 0 9px;font-size:10px}
.ir-prototype-activation__progress-label span{color:#8e8e93}
.ir-prototype-activation__progress{width:100%;height:10px;overflow:hidden;background:#e5e5ea;border-radius:999px}
.ir-prototype-activation__progress span{display:block;height:100%;background:linear-gradient(90deg,#ffb900,#ffd100);border-radius:inherit;transition:width .6s ease}
.ir-prototype-activation__card>.ir-button{margin-top:24px}

@media(max-width:900px){
