/* Student classes and profile */
.ir-student-classes-page,
.ir-student-profile-page{
 width:min(430px,100%);
 min-height:100svh;
 margin:0 auto;
 padding:18px 16px var(--ir-app-dock-space,110px);
 direction:rtl;
 color:#202024;
 background:#fffbe4;
 font-family:var(--ir-font-family)!important;
}

.ir-student-mobile-header{
 display:grid;
 grid-template-columns:44px minmax(0,1fr) 44px;
 align-items:center;
 gap:10px;
 margin-bottom:18px;
}

.ir-student-mobile-header>button{
 display:grid;
 width:44px;
 height:44px;
 padding:0;
 place-items:center;
 color:#202024;
 background:#fff;
 border:1px solid #e2dfcc;
 border-radius:14px;
 box-shadow:0 5px 15px rgba(48,42,9,.05);
}

.ir-student-mobile-header>button:first-child svg{
 transform:rotate(180deg);
}

.ir-student-mobile-header>div{
 min-width:0;
 text-align:center;
}

.ir-student-mobile-header h1{
 margin:0;
 overflow:hidden;
 font-size:18px;
 font-weight:1000;
 line-height:1.5;
 text-overflow:ellipsis;
 white-space:nowrap;
}

.ir-student-mobile-header p{
 margin:2px 0 0;
 color:#85858e;
 font-size:9px;
 line-height:1.5;
}

.ir-student-classes-summary{
 display:grid;
 grid-template-columns:54px minmax(0,1fr) auto;
 align-items:center;
 gap:12px;
 margin-bottom:16px;
 padding:16px;
 color:#202024;
 background:linear-gradient(145deg,#ffd100,#ffe783);
 border-radius:20px;
 box-shadow:0 10px 28px rgba(128,103,0,.12);
}

.ir-student-classes-summary__icon{
 display:grid;
 width:54px;
 height:54px;
 place-items:center;
 background:rgba(255,255,255,.65);
 border-radius:16px;
}

.ir-student-classes-summary>div:nth-child(2){
 display:grid;
 gap:2px;
 min-width:0;
}

.ir-student-classes-summary span{
 font-size:9px;
 font-weight:800;
}

.ir-student-classes-summary strong{
 font-size:27px;
 font-weight:1000;
 line-height:1.2;
}

.ir-student-classes-summary small{
 overflow:hidden;
 color:#675b20;
 font-size:7.5px;
 line-height:1.7;
 text-overflow:ellipsis;
 white-space:nowrap;
}

.ir-student-classes-summary>button{
 min-height:36px;
 padding:7px 10px;
 color:#fff;
 background:#202024;
 border:0;
 border-radius:11px;
 font-size:8px;
 font-weight:900;
 white-space:nowrap;
}

.ir-student-classes-tabs{
 display:grid;
 grid-template-columns:repeat(2,1fr);
 gap:5px;
 margin-bottom:14px;
 padding:4px;
 background:#eeebd9;
 border-radius:14px;
}

.ir-student-classes-tabs button{
 display:flex;
 align-items:center;
 justify-content:center;
 gap:6px;
 min-height:40px;
 color:#797983;
 background:transparent;
 border:0;
 border-radius:11px;
 font-size:9px;
 font-weight:900;
}

.ir-student-classes-tabs button span{
 display:grid;
 min-width:20px;
 height:20px;
 padding:0 5px;
 place-items:center;
 background:rgba(0,0,0,.06);
 border-radius:999px;
 font-size:7px;
}

.ir-student-classes-tabs button.is-active{
 color:#202024;
 background:#fff;
 box-shadow:0 4px 13px rgba(42,36,5,.07);
}

.ir-student-classes-list{
 display:grid;
 gap:12px;
}

.ir-student-class-card{
 overflow:hidden;
 padding:14px;
 background:#fff;
 border:1px solid #e5e2d4;
 border-radius:18px;
 box-shadow:0 8px 24px rgba(58,49,9,.05);
}

.ir-student-class-card.is-live{
 border-color:#ffd100;
 box-shadow:0 0 0 2px rgba(255,209,0,.12),0 8px 24px rgba(58,49,9,.07);
}

.ir-student-class-card>header{
 display:grid;
 grid-template-columns:46px minmax(0,1fr) auto;
 align-items:center;
 gap:10px;
}

.ir-student-class-card__date{
 display:grid;
 width:46px;
 height:50px;
 place-items:center;
 align-content:center;
 background:#fff6bf;
 border-radius:13px;
}

.ir-student-class-card__date b{
 font-size:16px;
 line-height:1.1;
}

.ir-student-class-card__date small{
 margin-top:2px;
 color:#6d632d;
 font-size:7px;
}

.ir-student-class-card>header>div{
 min-width:0;
}

.ir-student-class-card h2{
 margin:0;
 overflow:hidden;
 font-size:11px;
 font-weight:1000;
 line-height:1.7;
 text-overflow:ellipsis;
 white-space:nowrap;
}

.ir-student-class-card>header p{
 display:flex;
 align-items:center;
 gap:4px;
 margin:3px 0 0;
 color:#878790;
 font-size:7.5px;
 line-height:1.5;
}

.ir-student-class-card__details{
 display:grid;
 grid-template-columns:repeat(3,minmax(0,1fr));
 gap:6px;
 margin:13px 0;
 padding:10px;
 background:#f8f7f1;
 border-radius:12px;
}

.ir-student-class-card__details span{
 display:flex;
 min-width:0;
 align-items:center;
 justify-content:center;
 gap:4px;
 color:#6f6f78;
 font-size:7px;
 text-align:center;
}

.ir-student-class-card__details svg{
 flex:0 0 auto;
 width:15px;
 height:15px;
 fill:none;
 stroke:#202024;
 stroke-width:1.8;
 stroke-linecap:round;
 stroke-linejoin:round;
}

.ir-student-class-card__details b{
 overflow:hidden;
 font-weight:800;
 text-overflow:ellipsis;
 white-space:nowrap;
}

.ir-student-class-card>footer{
 display:grid;
 grid-template-columns:.8fr 1.2fr;
 gap:8px;
}

.ir-student-class-card>footer button{
 min-height:39px;
 border-radius:11px;
 font-size:8px;
 font-weight:1000;
}

.ir-student-class-card__secondary{
 color:#202024;
 background:#fff;
 border:1px solid #dddace;
}

.ir-student-class-card__primary{
 color:#202024;
 background:#ffd100;
 border:1px solid #ffd100;
}

.ir-student-mobile-empty{
 display:flex;
 min-height:340px;
 padding:32px 24px;
 flex-direction:column;
 align-items:center;
 justify-content:center;
 text-align:center;
 background:#fff;
 border:1px solid #e5e2d4;
 border-radius:20px;
}

.ir-student-mobile-empty>span{
 display:grid;
 width:64px;
 height:64px;
 place-items:center;
 color:#202024;
 background:#fff2a4;
 border-radius:20px;
}

.ir-student-mobile-empty h2{
 margin:16px 0 5px;
 font-size:15px;
}

.ir-student-mobile-empty p{
 max-width:280px;
 margin:0;
 color:#85858e;
 font-size:9px;
 line-height:1.9;
}

.ir-student-mobile-empty button{
 min-height:42px;
 margin-top:17px;
 padding:9px 18px;
 color:#202024;
 background:#ffd100;
 border:0;
 border-radius:12px;
 font-size:9px;
 font-weight:1000;
}

.ir-student-profile-hero{
 display:grid;
 grid-template-columns:68px minmax(0,1fr) auto;
 align-items:center;
 gap:13px;
 margin-bottom:13px;
 padding:16px;
 background:linear-gradient(145deg,#ffd100,#ffe783);
 border-radius:21px;
 box-shadow:0 10px 28px rgba(128,103,0,.12);
}

.ir-student-profile-hero__avatar{
 position:relative;
 width:68px;
 height:68px;
}

.ir-student-profile-hero__avatar>span{
 display:grid;
 width:68px;
 height:68px;
 place-items:center;
 color:#202024;
 background:#fff;
 border:3px solid rgba(255,255,255,.65);
 border-radius:21px;
 font-size:26px;
 font-weight:1000;
}

.ir-student-profile-hero__avatar>i{
 position:absolute;
 right:-3px;
 bottom:-3px;
 display:grid;
 width:25px;
 height:25px;
 place-items:center;
 color:#fff;
 background:#218557;
 border:3px solid #ffd100;
 border-radius:50%;
 font-style:normal;
}

.ir-student-profile-hero__identity{
 min-width:0;
}

.ir-student-profile-hero__identity h2{
 margin:0;
 overflow:hidden;
 font-size:16px;
 font-weight:1000;
 text-overflow:ellipsis;
 white-space:nowrap;
}

.ir-student-profile-hero__identity p{
 margin:3px 0;
 color:#655b2b;
 font-size:8px;
 line-height:1.5;
}

.ir-student-profile-hero__identity>span{
 display:flex;
 align-items:center;
 gap:5px;
 font-size:7px;
 font-weight:900;
}

.ir-student-profile-hero__identity>span i{
 width:7px;
 height:7px;
 background:#218557;
 border-radius:50%;
}

.ir-student-profile-hero>button{
 min-height:34px;
 padding:7px 10px;
 color:#202024;
 background:rgba(255,255,255,.72);
 border:0;
 border-radius:10px;
 font-size:8px;
 font-weight:1000;
}

.ir-student-profile-metrics{
 display:grid;
 grid-template-columns:repeat(3,1fr);
 gap:8px;
 margin-bottom:13px;
}

.ir-student-profile-metrics article{
 display:grid;
 min-width:0;
 padding:12px 5px;
 place-items:center;
 background:#fff;
 border:1px solid #e5e2d4;
 border-radius:15px;
 box-shadow:0 6px 18px rgba(58,49,9,.04);
}

.ir-student-profile-metrics span{
 display:grid;
 width:34px;
 height:34px;
 margin-bottom:5px;
 place-items:center;
 background:#fff4b4;
 border-radius:10px;
}

.ir-student-profile-metrics strong{
 font-size:15px;
 font-weight:1000;
}

.ir-student-profile-metrics small{
 margin-top:2px;
 color:#86868f;
 font-size:7px;
}

.ir-student-profile-section{
 margin-bottom:13px;
 padding:15px;
 background:#fff;
 border:1px solid #e5e2d4;
 border-radius:18px;
 box-shadow:0 7px 22px rgba(58,49,9,.04);
}

.ir-student-profile-section>header{
 display:flex;
 align-items:center;
 justify-content:space-between;
 margin-bottom:10px;
}

.ir-student-profile-section>header h2{
 margin:0;
 font-size:12px;
 font-weight:1000;
}

.ir-student-profile-section>header>span{
 padding:4px 8px;
 color:#177345;
 background:#e8f8ed;
 border-radius:999px;
 font-size:7px;
 font-weight:900;
}

.ir-student-profile-details{
 margin:0;
}

.ir-student-profile-details>div{
 display:flex;
 align-items:center;
 justify-content:space-between;
 gap:12px;
 min-height:43px;
 border-bottom:1px solid #efede5;
}

.ir-student-profile-details>div:last-child{
 border-bottom:0;
}

.ir-student-profile-details dt{
 display:flex;
 align-items:center;
 gap:7px;
 color:#787881;
 font-size:8px;
}

.ir-student-profile-details dt svg{
 width:17px;
 height:17px;
 fill:none;
 stroke:#202024;
 stroke-width:1.8;
 stroke-linecap:round;
 stroke-linejoin:round;
}

.ir-student-profile-details dd{
 max-width:55%;
 margin:0;
 overflow:hidden;
 color:#202024;
 font-size:8.5px;
 font-weight:900;
 text-align:left;
 text-overflow:ellipsis;
 white-space:nowrap;
}

.ir-student-profile-actions{
 display:grid;
 gap:4px;
}

.ir-student-profile-actions>button{
 display:grid;
 grid-template-columns:40px minmax(0,1fr) 20px;
 align-items:center;
 gap:10px;
 min-height:58px;
 padding:8px 0;
 color:#202024;
 text-align:right;
 background:transparent;
 border:0;
 border-bottom:1px solid #efede5;
}

.ir-student-profile-actions>button:last-child{
 border-bottom:0;
}

.ir-student-profile-actions>button>span{
 display:grid;
 width:40px;
 height:40px;
 place-items:center;
 background:#fff3ad;
 border-radius:12px;
}

.ir-student-profile-actions>button>div{
 display:grid;
 gap:3px;
 min-width:0;
}

.ir-student-profile-actions strong{
 font-size:9px;
}

.ir-student-profile-actions small{
 overflow:hidden;
 color:#888890;
 font-size:7px;
 text-overflow:ellipsis;
 white-space:nowrap;
}

.ir-student-profile-actions>button>svg:last-child{
 transform:rotate(180deg);
}

.ir-student-profile-logout{
 width:100%;
 min-height:45px;
 color:#b42318;
 background:#fff;
 border:1px solid #efc8c5;
 border-radius:13px;
 font-size:9px;
 font-weight:1000;
}

.ir-route-layer-host.has-persistent-dock .ir-student-classes-page,
.ir-route-layer-host.has-persistent-dock .ir-student-profile-page{
 padding-bottom:var(--ir-app-dock-space)!important;
}

@media(min-width:431px){
 .ir-student-classes-page,
 .ir-student-profile-page{
  border-right:1px solid #e7e3cf;
  border-left:1px solid #e7e3cf;
 }
}

@media(max-width:360px){
 .ir-student-classes-page,
 .ir-student-profile-page{
  padding-right:12px;
  padding-left:12px;
 }

 .ir-student-classes-summary{
  grid-template-columns:48px minmax(0,1fr);
 }

 .ir-student-classes-summary>button{
  grid-column:1/-1;
 }

 .ir-student-class-card__details{
  grid-template-columns:1fr;
 }

 .ir-student-profile-hero{
  grid-template-columns:60px minmax(0,1fr);
 }

 .ir-student-profile-hero__avatar,
 .ir-student-profile-hero__avatar>span{
  width:60px;
  height:60px;
 }

 .ir-student-profile-hero>button{
  grid-column:1/-1;
 }
}


/* Final readable UI system for every role and page. */
html,body,#root{font-family:var(--ir-font-family)!important;font-size:16px!important;line-height:1.75!important;text-rendering:optimizeLegibility;-webkit-font-smoothing:antialiased}
body{color:#202024!important;background:#f7f7f2!important}
svg text{font-family:var(--ir-font-family)!important}
button,input,textarea,select,option{font-family:var(--ir-font-family)!important;font-size:14px!important;line-height:1.6!important}
button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid rgba(255,209,0,.42)!important;outline-offset:2px!important}

.ir-screen-surface{
 --ir-page-gutter:clamp(20px,5vw,40px);
 width:100%!important;
 max-width:none!important;
 height:100%!important;
 min-height:0!important;
 margin:0!important;
 box-sizing:border-box!important;
}

.ir-screen-surface>*{
 width:100%!important;
 min-width:0!important;
 max-width:none!important;
 margin-right:0!important;
 margin-left:0!important;
 box-sizing:border-box!important;
}

.ir-screen-surface.is-full-bleed{
 padding:0!important;
 overflow:hidden!important;
 background:#fffbe4!important;
}

.ir-screen-surface.is-full-bleed>*{
 width:100%!important;
 max-width:none!important;
}

.ir-screen-surface.is-standard{
 width:100%!important;
 max-width:none!important;
 padding:var(--ir-page-gutter)!important;
 overflow-x:hidden!important;
 overflow-y:auto!important;
 background:linear-gradient(180deg,#fffdf2 0,#f7f7f2 240px)!important;
 scrollbar-gutter:stable;
}

.ir-screen-surface.is-standard>*{
 width:100%!important;
 min-width:0!important;
 max-width:none!important;
 margin:0!important;
}

.ir-route-layer-host.has-persistent-dock .ir-screen-surface.is-standard{
