/* Final Irancell typography + interface normalization                        */
/* -------------------------------------------------------------------------- */

:root{
 --ir-type-display:clamp(24px,6.3vw,30px);
 --ir-type-page-title:clamp(19px,5.1vw,22px);
 --ir-type-section-title:clamp(15px,4.1vw,17px);
 --ir-type-card-title:clamp(13px,3.5vw,15px);
 --ir-type-body:clamp(11.5px,3vw,13px);
 --ir-type-body-small:clamp(10.5px,2.7vw,12px);
 --ir-type-caption:clamp(9.5px,2.45vw,11px);
 --ir-type-micro:clamp(9px,2.25vw,10px);
 --ir-type-button:clamp(11.5px,3vw,13px);
 --ir-line-body:1.9;
 --ir-line-title:1.55;
 --ir-mobile-page-padding:clamp(18px,5.5vw,30px);
}

/* Enforce Vazirmatn across every Irancell-owned UI surface and form control. */
body :where(
 [class^="ir-"],
 [class*=" ir-"],
 [class^="irancell-"],
 [class*=" irancell-"]
),
body :where(
 [class^="ir-"],
 [class*=" ir-"],
 [class^="irancell-"],
 [class*=" irancell-"]
) :where(button,input,textarea,select,option){
 font-family:var(--ir-font-family)!important;
 font-variant-numeric:normal!important;
}

/* Do not allow inherited browser fonts inside controls. */
body :where(
 [class^="ir-"],
 [class*=" ir-"]
) :where(button,input,textarea,select){
 letter-spacing:0!important;
}

