 box-sizing:border-box!important;
 font-family:var(--ir-font-family)!important;
}

.ir-chisti-attachment-state{
 position:relative!important;
 display:grid!important;
 grid-template-columns:48px minmax(0,1fr) 30px!important;
 align-items:center!important;
 gap:12px!important;
 width:100%!important;
 min-height:64px!important;
 margin:10px 0 0!important;
 padding:8px 12px!important;
 direction:ltr!important;
 color:#1d1d20!important;
 background:#f5f5f5!important;
 border:0!important;
 border-radius:12px!important;
 box-shadow:none!important;
 overflow:hidden!important;
}

.ir-chisti-attachment-state__preview{
 position:relative!important;
 display:grid!important;
 grid-column:1!important;
 width:48px!important;
 height:48px!important;
 place-items:center!important;
 overflow:visible!important;
 color:#696969!important;
 background:#dedede!important;
 border-radius:8px!important;
}

.ir-chisti-attachment-state__preview img{
 width:48px!important;
 height:48px!important;
 object-fit:cover!important;
 border-radius:8px!important;
}

.ir-chisti-attachment-state__preview>svg{
 width:26px!important;
 height:26px!important;
 fill:none!important;
 stroke:currentColor!important;
 stroke-width:1.9!important;
 stroke-linecap:round!important;
 stroke-linejoin:round!important;
}

.ir-chisti-attachment-state__copy{
 grid-column:2!important;
 min-width:0!important;
 direction:rtl!important;
 text-align:right!important;
}

.ir-chisti-attachment-state__copy strong{
 display:block!important;
 max-width:100%!important;
 overflow:hidden!important;
 color:#202024!important;
 font-size:14px!important;
 font-weight:800!important;
 line-height:1.7!important;
 text-overflow:ellipsis!important;
 white-space:nowrap!important;
}

.ir-chisti-attachment-state__copy small{
 display:block!important;
 margin-top:2px!important;
 color:#76777d!important;
 font-size:10px!important;
 font-weight:500!important;
 line-height:1.5!important;
}

.ir-chisti-attachment-state__copy small.is-uploading-text{
 color:#c99d00!important;
 font-size:11px!important;
 font-weight:700!important;
}

.ir-chisti-attachment-state__remove{
 grid-column:3!important;
 display:grid!important;
 width:24px!important;
 height:24px!important;
 place-items:center!important;
 justify-self:end!important;
 margin:0!important;
 padding:0!important;
 color:#707175!important;
 background:#e0e0e0!important;
 border:0!important;
 border-radius:50%!important;
 box-shadow:none!important;
}

.ir-chisti-attachment-state__remove svg{
 width:18px!important;
 height:18px!important;
 fill:none!important;
 stroke:currentColor!important;
 stroke-width:2!important;
 stroke-linecap:round!important;
 stroke-linejoin:round!important;
}

.ir-chisti-attachment-state.is-uploading{
 min-height:72px!important;
 padding-bottom:14px!important;
}

.ir-chisti-attachment-state.is-uploading .ir-chisti-attachment-state__preview{
 width:40px!important;
 height:40px!important;
 margin-left:4px!important;
}

.ir-chisti-attachment-state.is-uploading .ir-chisti-attachment-state__preview>svg{
 width:25px!important;
 height:25px!important;
}

.ir-chisti-attachment-state__progress{
 position:absolute!important;
 right:0!important;
 bottom:0!important;
 left:0!important;
 width:100%!important;
 height:4px!important;
 overflow:hidden!important;
 direction:ltr!important;
 background:#dedede!important;
 border-radius:0!important;
}

.ir-chisti-attachment-state__progress>span{
 display:block!important;
 height:100%!important;
 background:#ffd100!important;
 border-radius:0!important;
 transition:width .18s linear!important;
}

.ir-chisti-attachment-state.is-success:not(.is-image){
 background:#ecfff2!important;
}

.ir-chisti-attachment-state.is-success:not(.is-image) .ir-chisti-attachment-state__preview{
 color:#22c55e!important;
 background:#c9f6d7!important;
}

.ir-chisti-attachment-state__success-mark{
 position:absolute!important;
 right:-6px!important;
 bottom:-6px!important;
 display:grid!important;
 width:19px!important;
 height:19px!important;
 place-items:center!important;
 color:#fff!important;
 background:#22c55e!important;
 border:2px solid #fff!important;
 border-radius:50%!important;
 font-size:11px!important;
 font-style:normal!important;
 font-weight:900!important;
 line-height:1!important;
}

.ir-chisti-attachment-state.is-failed{
 display:grid!important;
 grid-template-columns:48px minmax(0,1fr) auto!important;
 min-height:64px!important;
 color:#ef4444!important;
 background:#fff0f0!important;
}

.ir-chisti-attachment-state__failed-icon{
 display:grid!important;
 grid-column:1!important;
 width:40px!important;
 height:40px!important;
 place-items:center!important;
 color:#ff4545!important;
 background:#ffd5d5!important;
 border-radius:8px!important;
}

.ir-chisti-attachment-state__failed-icon svg{
 width:26px!important;
 height:26px!important;
 fill:none!important;
 stroke:currentColor!important;
 stroke-width:2!important;
 stroke-linecap:round!important;
 stroke-linejoin:round!important;
}

.ir-chisti-attachment-state.is-failed>strong{
 grid-column:2!important;
 direction:rtl!important;
 color:#f04444!important;
 font-size:13px!important;
 font-weight:900!important;
 line-height:1.6!important;
 text-align:right!important;
}

.ir-chisti-attachment-state__retry{
 grid-column:3!important;
 min-height:34px!important;
 margin:0!important;
 padding:4px 8px!important;
 color:#b98d00!important;
 background:transparent!important;
 border:0!important;
 border-bottom:1px solid #cda200!important;
 border-radius:0!important;
 box-shadow:none!important;
 font-size:11px!important;
 font-weight:900!important;
 white-space:nowrap!important;
}

.ir-chisti-search-page>.ir-chisti-attachment-state,
.ir-chisti-results-page>.ir-chisti-attachment-state,
.ir-shared-file-uploader>.ir-chisti-attachment-state,
.ir-new-class-request__attachment .ir-chisti-attachment-state,
.ir-exact-student-dashboard__chisty .ir-chisti-attachment-state{
 width:100%!important;
}

.ir-exact-student-dashboard__chisty>.ir-shared-file-uploader.is-external-trigger{
 grid-column:1/-1!important;
 grid-row:auto!important;
 display:block!important;
 width:100%!important;
 min-width:0!important;
 margin:0!important;
}

.ir-exact-student-dashboard__chisty>.ir-shared-file-uploader.is-external-trigger:not(:has(.ir-chisti-attachment-state)){
 height:0!important;
 min-height:0!important;
 overflow:hidden!important;
}

.ir-exact-student-dashboard__chisty>.ir-shared-file-uploader.is-external-trigger .ir-chisti-attachment-state{
 margin-top:2px!important;
 background:#f7f7f8!important;
 border:1px solid rgba(255,255,255,.1)!important;
}

