/* Responsive Chisty main chat */
.ir-chisti-main-chat{
 width:100%;
 min-width:0;
 min-height:100dvh;
 display:grid;
 grid-template-columns:minmax(270px,320px) minmax(0,1fr);
 direction:rtl;
 background:#f6f5ef;
 color:#1e1e20;
 overflow:hidden;
}

.ir-chisti-main-chat__scrim{
 display:none;
}

.ir-chisti-main-chat__sidebar{
 min-width:0;
 height:100dvh;
 display:flex;
 flex-direction:column;
 gap:14px;
 padding:20px 16px calc(104px + env(safe-area-inset-bottom));
 background:#1c1c1f;
 color:#fff;
 border-left:1px solid rgba(255,255,255,.08);
 overflow:hidden;
}

.ir-chisti-main-chat__sidebar-header{
 display:flex;
 align-items:center;
 justify-content:space-between;
 gap:12px;
}

.ir-chisti-main-chat__sidebar-header>div{
 min-width:0;
 display:flex;
 align-items:center;
 gap:10px;
}

.ir-chisti-main-chat__sidebar-header>div>div{
 min-width:0;
 display:flex;
 flex-direction:column;
 gap:2px;
}

.ir-chisti-main-chat__sidebar-header strong{
 font-size:17px;
}

.ir-chisti-main-chat__sidebar-header small{
 color:#a9a9b0;
 font-size:10px;
}

.ir-chisti-main-chat__brand-mark{
 width:42px;
 height:42px;
 flex:0 0 42px;
 display:grid;
 place-items:center;
 border-radius:15px;
 background:#ffd100;
 color:#161616;
 font-size:22px;
 font-weight:1000;
 box-shadow:0 8px 24px rgba(255,209,0,.18);
}

.ir-chisti-main-chat__sidebar-close{
 display:none;
 width:38px;
 height:38px;
 border:0;
 border-radius:12px;
 background:#2b2b2f;
 color:#fff;
 font-size:26px;
 line-height:1;
}

.ir-chisti-main-chat__new{
 width:100%;
 min-height:48px;
 display:flex;
 align-items:center;
 justify-content:center;
 gap:8px;
 border:0;
 border-radius:15px;
 background:#ffd100;
 color:#161616;
 font-weight:900;
}

.ir-chisti-main-chat__new span{
 font-size:20px;
}

.ir-chisti-main-chat__search{
 min-height:44px;
 display:flex;
 align-items:center;
 gap:8px;
 padding:0 12px;
 border:1px solid #37373c;
 border-radius:14px;
 background:#26262a;
}

.ir-chisti-main-chat__search svg{
 width:18px;
 height:18px;
 fill:none;
 stroke:#96969e;
 stroke-width:2;
}

.ir-chisti-main-chat__search input{
 width:100%;
 min-width:0;
 border:0;
 outline:0;
 background:transparent;
 color:#fff;
 font-size:12px;
}

.ir-chisti-main-chat__search input::placeholder{
 color:#898990;
}

.ir-chisti-main-chat__conversation-list{
 min-height:0;
 flex:1;
 display:flex;
 flex-direction:column;
 gap:6px;
 overflow-y:auto;
 overscroll-behavior:contain;
 scrollbar-width:thin;
}

.ir-chisti-main-chat__conversation-list>button{
 width:100%;
 min-width:0;
 display:grid;
 grid-template-columns:34px minmax(0,1fr) auto;
 align-items:center;
 gap:9px;
 padding:10px;
 border:1px solid transparent;
 border-radius:13px;
 background:transparent;
 color:#dedee2;
 text-align:right;
}

.ir-chisti-main-chat__conversation-list>button:hover,
.ir-chisti-main-chat__conversation-list>button.is-active{
 background:#2b2b30;
 border-color:#3d3d43;
}

.ir-chisti-main-chat__conversation-list>button.is-active{
 box-shadow:inset -3px 0 #ffd100;
}

.ir-chisti-main-chat__conversation-list>button>span:nth-child(2){
 min-width:0;
 display:flex;
 flex-direction:column;
 gap:4px;
}

.ir-chisti-main-chat__conversation-list strong{
 overflow:hidden;
 text-overflow:ellipsis;
 white-space:nowrap;
 font-size:12px;
}

.ir-chisti-main-chat__conversation-list small{
 overflow:hidden;
 text-overflow:ellipsis;
 white-space:nowrap;
 color:#96969e;
 font-size:9px;
}

.ir-chisti-main-chat__conversation-icon{
 width:34px;
 height:34px;
 display:grid;
 place-items:center;
 border-radius:11px;
 background:#36363b;
 color:#ffd100;
}

.ir-chisti-main-chat__processing-dot{
 width:8px;
 height:8px;
 border-radius:50%;
 background:#ffd100;
 box-shadow:0 0 0 5px rgba(255,209,0,.1);
 animation:ir-chisti-main-pulse 1.2s infinite;
}

@keyframes ir-chisti-main-pulse{
 50%{transform:scale(.75);opacity:.55}
}

.ir-chisti-main-chat__sidebar-empty{
 min-height:170px;
 display:flex;
 flex-direction:column;
 align-items:center;
 justify-content:center;
 gap:5px;
 padding:18px;
 text-align:center;
}

.ir-chisti-main-chat__sidebar-empty small{
 color:#96969e;
 line-height:1.8;
}

.ir-chisti-main-chat__workspace{
 min-width:0;
 height:100dvh;
 display:grid;
 grid-template-rows:auto minmax(0,1fr) auto;
 background:#fffdf5;
 overflow:hidden;
}

.ir-chisti-main-chat__topbar{
 min-width:0;
 min-height:72px;
 display:flex;
 align-items:center;
 justify-content:space-between;
 gap:14px;
 padding:12px clamp(16px,3vw,32px);
 border-bottom:1px solid #e8e5d8;
 background:rgba(255,253,245,.94);
 backdrop-filter:blur(14px);
 z-index:5;
}

.ir-chisti-main-chat__topbar-start{
 min-width:0;
 display:flex;
 align-items:center;
 gap:10px;
}

.ir-chisti-main-chat__topbar-start>div{
 min-width:0;
 display:flex;
 flex-direction:column;
 gap:3px;
}

.ir-chisti-main-chat__topbar-start strong{
 max-width:min(56vw,620px);
 overflow:hidden;
 text-overflow:ellipsis;
 white-space:nowrap;
 font-size:14px;
}

.ir-chisti-main-chat__topbar-start small{
 color:#85858c;
 font-size:10px;
}

.ir-chisti-main-chat__back,
.ir-chisti-main-chat__list-toggle{
 width:40px;
 height:40px;
 flex:0 0 40px;
 display:grid;
 place-items:center;
 padding:0;
 border:1px solid #e2dfd4;
 border-radius:13px;
 background:#fff;
 color:#202024;
}

.ir-chisti-main-chat__back svg,
.ir-chisti-main-chat__list-toggle svg{
 width:21px;
 height:21px;
 fill:none;
 stroke:currentColor;
 stroke-width:2;
 stroke-linecap:round;
 stroke-linejoin:round;
}

.ir-chisti-main-chat__list-toggle{
 display:none;
}

.ir-chisti-main-chat__history-button{
 min-height:40px;
 padding:8px 14px;
 border:1px solid #dedace;
 border-radius:12px;
 background:#fff;
 color:#36363a;
 font-size:11px;
 font-weight:800;
}

.ir-chisti-main-chat__messages{
 min-width:0;
 min-height:0;
 width:100%;
 max-width:940px;
 margin-inline:auto;
 padding:clamp(18px,3vw,34px) clamp(14px,4vw,42px);
 overflow-y:auto;
 overscroll-behavior:contain;
 scrollbar-gutter:stable;
}

.ir-chisti-main-chat__welcome{
