 display:grid;
 grid-template-columns:repeat(2,minmax(0,1fr));
 gap:10px;
 margin-top:12px;
}

.ir-chisti-main-chat__welcome>div>button{
 min-width:0;
 min-height:92px;
 display:flex;
 flex-direction:column;
 align-items:flex-start;
 gap:6px;
 padding:14px;
 border:1px solid #e2dfd4;
 border-radius:16px;
 background:#fff;
 text-align:right;
}

.ir-chisti-main-chat__welcome>div>button:hover{
